# Try: for each input row, best matching output row = the one minimizing mismatches confined to six-positions, allowing one missing token.
def best_match(t):
    t=list(t)
    best=None
    for k in range(30):
        o=od[k].tolist()
        # try aligning t (length 30) to o: mismatches allowed only where t==6, plus allow one insertion in t (a lost token)
        # case A: same length
        def score(tt):
            mism=[j for j in range(30) if tt[j]!=o[j]]
            return all(tt[j]==6 for j in mism), len(mism)
        okA, sA = score(t)
        cands=[]
        if okA: cands.append((sA,'A',None))
        # case B: one token missing -> try inserting a 6 at each position
        for p in range(31):
            tt = t[:p]+[6]+t[p:]
            if len(tt)!=30: continue
            ok,s = score(tt)
            if ok: cands.append((s,'B',p))
        if cands:
            cands.sort()
            if best is None or cands[0][0]<best[0]:
                best=(cands[0][0], k, cands[0])
    return best
